// Active asset allowlist: the ONLY assets the app may offer or accept.
//
// Source: src/data/activeAssetAllowlist.json, generated by
// base-contracts/scripts/buildAppAllowlist.cjs from Revision B
// (base-contracts/deployment/assetRegistry.revB.json, 487 entries) and the
// 2026-10-20 on-chain verification. A token is offerable only if it is on
// Revision B AND passed on-chain verification. Anything else is hidden: failed
// verification, never checked, not in Revision B, and every Solana row.
//
// Matching never uses a ticker alone:
//   token  -> environment + contract address (case-insensitive)
//   native -> environment + native id (e.g. native-BTC)
// Every entry path (asset pickers, saved or initial state, URL values, manual
// addresses, proof packages) goes through resolveOfferable or
// isOfferablePackageAsset, so a value that did not come from the picker is
// refused the same way.
//
// Token verification status (second gate): src/data/tokenVerificationStatus.json,
// generated by testing-rigs/registry-verify/buildCandidate.cjs from the
// 2026-10-23 on-chain check. An allowlisted token is offered only if its own
// row (environment + address + row) has status "pass" there. A token whose row
// failed, is "unchecked", or has no record at all (never checked) is hidden.
// Natives are not address-bearing and are governed by the allowlist alone.
// Every function that matches a token accepts an optional last argument
// { statusIndex } (from buildStatusIndex) so tests can supply another status file.
import ALLOWLIST from '../data/activeAssetAllowlist.json' with { type: 'json' };
import TOKEN_STATUS from '../data/tokenVerificationStatus.json' with { type: 'json' };
import { findAssetPrecision } from './vfBaseRegistry.js';

// App and hosted-registry environment names -> Revision B environment ids.
const ENV_ALIASES = {
  XRPL: 'XRP Ledger', BNB: 'BNB Smart Chain', BSC: 'BNB Smart Chain', BitcoinCash: 'Bitcoin Cash',
};
export function normalizeEnvironment(env) {
  const s = String(env ?? '').trim();
  return ENV_ALIASES[s] || s;
}

const ADDR = /^0x[0-9a-fA-F]{40}$/;
const ZERO = /^0x0{40}$/;
const HASH = /^0x[0-9a-fA-F]{64}$/;

const TOKENS = new Map();
const NATIVES = new Map();
const BY_CANONICAL = new Map();
for (const e of ALLOWLIST.entries) {
  if (e.kind === 'token') TOKENS.set(`${e.environmentId}|${e.address.toLowerCase()}`, e);
  else NATIVES.set(`${e.environmentId}|${e.nativeId}`, e);
  BY_CANONICAL.set(`${e.environmentId}|${e.canonicalAssetId.toLowerCase()}`, e);
}
for (const l of ALLOWLIST.nativeLinks) {
  NATIVES.set(`${l.environmentId}|${l.nativeId}`, l);
  BY_CANONICAL.set(`${l.environmentId}|${l.canonicalAssetId.toLowerCase()}`, l);
}

// statusFile: { records: [{ environmentId, row, address, status, reason? }] }
export function buildStatusIndex(statusFile) {
  const m = new Map();
  for (const r of (statusFile && statusFile.records) || []) {
    m.set(`${normalizeEnvironment(r.environmentId)}|${String(r.address).toLowerCase()}|${Number(r.row)}`, r);
  }
  return m;
}
const STATUS_INDEX = buildStatusIndex(TOKEN_STATUS);
export const TOKEN_VERIFICATION_STATUS = TOKEN_STATUS;

// { status: 'pass' | 'fail' | 'unchecked', reason } for an allowlisted token entry.
// A token with no record was never checked: 'unchecked', reason 'never_checked'.
export function tokenVerification(entry, { statusIndex = STATUS_INDEX } = {}) {
  if (!entry || entry.kind !== 'token') return { status: 'unchecked', reason: 'not_a_token' };
  const r = statusIndex.get(`${entry.environmentId}|${String(entry.address).toLowerCase()}|${Number(entry.row)}`);
  if (!r) return { status: 'unchecked', reason: 'never_checked' };
  if (r.status === 'pass') return { status: 'pass', reason: null };
  return { status: r.status === 'fail' ? 'fail' : 'unchecked', reason: r.reason || r.status };
}
export function isVerifiedToken(entry, opts) { return tokenVerification(entry, opts).status === 'pass'; }

export const ACTIVE_ALLOWLIST = ALLOWLIST;
export const ACTIVE_ALLOWLIST_COUNT = ALLOWLIST.entries.length;
// What the app actually offers: allowlisted natives plus allowlisted tokens that passed verification.
export const OFFERED_ENTRIES = ALLOWLIST.entries.filter((e) => e.kind !== 'token' || isVerifiedToken(e));
export const OFFERED_COUNT = OFFERED_ENTRIES.length;

// The allowlist entry for (env, address), verified or not (for reasons and audit).
function lookupToken(env, address) {
  const e = normalizeEnvironment(env);
  if (e === 'Solana' || !ADDR.test(String(address ?? '')) || ZERO.test(address)) return null;
  return TOKENS.get(`${e}|${address.toLowerCase()}`) || null;
}
// The offerable token for (env, address): on the allowlist AND verified.
export function findAllowedToken(env, address, opts) {
  const entry = lookupToken(env, address);
  return entry && isVerifiedToken(entry, opts) ? entry : null;
}
export function findAllowedNative(env, nativeId) {
  const e = normalizeEnvironment(env);
  if (e === 'Solana') return null;
  return NATIVES.get(`${e}|${String(nativeId ?? '')}`) || null;
}

// True for the registry's native markers: "NATIVE ...", or the zero address.
export function isNativeIdentifier(id) {
  const s = String(id ?? '').trim();
  return /^NATIVE\b/i.test(s) || ZERO.test(s);
}

// record: a hosted-registry record { registry_row, environment, contract_or_native_identifier, symbol }
// or an app registry entry with the same fields. Returns { ok, entry, reason }.
// When the record carries a registry row, it must be the allowlisted entry's own
// row: another row that sits on the same address (an alias such as USDC_ETH, or a
// mislabelled row such as 152 "ACM" on MKR's address) is not shown.
export function resolveOfferable(record, opts) {
  const r = resolveByKey(record, opts);
  if (!r.ok) return r;
  const row = record.registry_row;
  if (row != null && r.entry.row != null && Number(row) !== Number(r.entry.row)) return { ok: false, reason: 'row_not_on_active_list' };
  return r;
}
function resolveByKey(record, opts) {
  if (!record) return { ok: false, reason: 'no_asset' };
  const env = normalizeEnvironment(record.environment ?? record.environmentId);
  if (env === 'Solana') return { ok: false, reason: 'solana_hidden' };
  const id = String(record.contract_or_native_identifier ?? record.address ?? record.identifier ?? '').trim();
  if (isNativeIdentifier(id)) {
    const nativeId = record.nativeId || `native-${record.symbol}`;
    const entry = findAllowedNative(env, nativeId);
    return entry ? { ok: true, entry } : { ok: false, reason: 'native_not_on_active_list' };
  }
  if (ADDR.test(id)) {
    const entry = lookupToken(env, id);
    if (!entry) return { ok: false, reason: 'token_not_on_active_list' };
    const v = tokenVerification(entry, opts);
    if (v.status === 'fail') return { ok: false, reason: 'token_failed_verification', detail: v.reason };
    if (v.status !== 'pass') return { ok: false, reason: 'token_not_verified', detail: v.reason };
    return { ok: true, entry };
  }
  return { ok: false, reason: 'no_contract_or_native_identifier' }; // ticker-only: refused
}
export function isOfferable(record, opts) { return resolveOfferable(record, opts).ok; }
export function filterOfferable(records, opts) { return (records || []).filter((r) => isOfferable(r, opts)); }

// Proof-package path: (source_environment_id, canonical_asset_id) as the app's
// normalizers produce them ("native-ETH", an app short id such as "USDC", a
// contract address, or a canonical 32-byte id).
export function isOfferablePackageAsset(envId, canonicalAssetId, opts) {
  const env = normalizeEnvironment(envId);
  const id = String(canonicalAssetId ?? '');
  if (env === 'Solana' || !id) return false;
  if (id.startsWith('native-')) return !!findAllowedNative(env, id);
  if (ADDR.test(id)) return !!findAllowedToken(env, id, opts);
  if (HASH.test(id)) {
    const entry = BY_CANONICAL.get(`${env}|${id.toLowerCase()}`);
    return !!entry && (entry.kind !== 'token' || isVerifiedToken(entry, opts));
  }
  const listed = findAssetPrecision(envId, id); // app short id -> its contract address
  return !!(listed && listed.contract && findAllowedToken(env, listed.contract, opts));
}

export const NOT_ACTIVE_MESSAGE = 'VF-REG-001: asset is not on the active asset list (Revision B with on-chain verification); it is not offered';

// The native asset each app environment's simulated lock uses (vfMockEventBuilder).
const APP_ENV_NATIVE_ID = {
  Ethereum: 'native-ETH', Base: 'native-ETH', Optimism: 'native-ETH', Arbitrum: 'native-ETH',
  BNB: 'native-BNB', Avalanche: 'native-AVAX', Polygon: 'native-POL', Solana: 'native-SOL',
  Bitcoin: 'native-BTC', Litecoin: 'native-LTC', Dogecoin: 'native-DOGE', DigiByte: 'native-DGB',
  Zcash: 'native-ZEC', BitcoinCash: 'native-BCH', XRPL: 'native-XRP', Stellar: 'native-XLM',
};
export function isOfferableEnvironmentNative(appEnv) {
  const id = APP_ENV_NATIVE_ID[appEnv];
  return !!id && isOfferablePackageAsset(appEnv, id);
}
